import { SANITY_FUNCTION_PREFIX } from '../../constants.js';
import { resolveDeployedResources } from '../../utils/blueprints/resolve-deployed-resources.js';
import { BUNDLE_SPECS, prepareBundleAsset, } from '../../utils/bundles/prepare-asset.js';
import { CODE_OPERATION_UNCONFIRMED, EXIT_OPERATION_UNCONFIRMED } from '../../utils/exit-codes.js';
import { prepareAsset as prepareFunctionAsset } from '../../utils/functions/prepare-asset.js';
import { runCommand } from '../../utils/package-manager.js';
import { setupLogPolling } from './logs-polling.js';
import { getOperationStateInfo } from './operations-state.js';
import { processAssets } from './process-assets.js';
import { updateStack } from './stacks.js';
/**
 * A list of configurations for pre-deployment of resources. The first resourceType to match in the list will take precedence.
 */
const preDeployConfigs = [
    {
        resourceType: (type) => type in BUNDLE_SPECS,
        async prepareAsset(options) {
            return prepareBundleAsset({
                resource: options.resource,
                blueprintFileDir: options.blueprintFileDir,
            });
        },
    },
    {
        resourceType: (type) => type.startsWith(SANITY_FUNCTION_PREFIX),
        async prepareAsset(options) {
            return prepareFunctionAsset({
                resource: options.resource,
                blueprintFileDir: options.blueprintFileDir,
                installer: options.installer,
            });
        },
    },
];
function hasPreDeployResources(resources) {
    return resources.some((r) => {
        return !!getPredeployConfig(r);
    });
}
function getPredeployConfig(r) {
    return preDeployConfigs.find((c) => {
        return ((typeof c.resourceType === 'function' && c.resourceType(r.type)) ||
            (typeof c.resourceType !== 'function' && c.resourceType === r.type));
    });
}
export async function preDeploy(options) {
    const { resources, stackId, auth, blueprintFileDir, installer, fetchFn } = options;
    const resourceMetadata = [];
    if (hasPreDeployResources(resources)) {
        const preDeployStackResult = await preDeployStack(options);
        if (!preDeployStackResult.success) {
            return preDeployStackResult;
        }
        /** Look up resources from the back-end and attach the externalId if possible */
        const resolvedResources = await resolveDeployedResources({
            resources,
            stackId,
            auth,
            fetchFn,
        });
        const assetResources = [];
        for (const r of resolvedResources) {
            const config = getPredeployConfig(r);
            if (typeof config !== 'undefined' && typeof config.prepareAsset === 'function') {
                assetResources.push({ resource: r, prepareAsset: config.prepareAsset });
            }
        }
        let processedAssets = [];
        try {
            processedAssets = await processAssets({
                assetResources,
                auth,
                blueprintFileDir,
                installer,
                fetchFn,
                onProgress: (progress) => options.onAssetEvent?.({ type: 'progress', progress }),
                onResult: (result) => options.onAssetEvent?.({ type: 'result', result }),
            });
        }
        finally {
            options.onAssetEvent?.({ type: 'complete' });
        }
        const failure = processedAssets.find((result) => !result.success);
        if (failure)
            return { success: false, error: failure.error };
        // update resources with processed assets
        for (const asset of processedAssets) {
            const idx = resources.findIndex((r) => r.name === asset.resource.name);
            // ! I think this error message is wrong. we somehow have an extra asset
            if (idx === -1)
                throw new Error('Unable to update resource asset');
            resources[idx] = asset.resource;
            if (asset.success) {
                const { name, type } = asset.resource;
                resourceMetadata.push({
                    name,
                    type,
                    assetHash: asset.hash,
                    assetReused: asset.exists,
                    ...asset.metadata,
                });
            }
        }
    }
    return { success: true, resourceMetadata };
}
async function preDeployStack(options) {
    const { scopeType, scopeId, stackId, stackName, resources, auth, bin, fetchFn, waitForFn } = options;
    options.onPreDeployStackStart?.();
    const stackMutation = {
        scopeType,
        scopeId,
        name: stackName,
        preDeploy: true,
        document: { resources },
    };
    const { ok: deployOk, stack, error: deployError, requestId, } = await updateStack({ stackId, stackMutation, auth, fetchFn });
    if (!deployOk) {
        options.onPreDeployStackFail?.();
        return {
            success: false,
            error: deployError || 'Failed to complete Stack pre-deployment',
            requestId,
            suggestions: [
                `Run \`${runCommand(bin)} blueprints plan\` to preview changes before deploying.`,
                `Run \`${runCommand(bin)} blueprints doctor\` to check your configuration.`,
            ],
        };
    }
    options.onPreDeployStackDone?.();
    if (stack.changeCount === 0)
        return { success: true };
    options.onPreDeployOperationStart?.();
    const outcome = await waitForFn({
        getIdleMessage() {
            return `The pre-deployment is still running on Sanity servers.`;
        },
        async onRequestLatestState() {
            return await getOperationStateInfo({
                stackId,
                operationId: stack.operationId,
                auth,
                fetchFn,
                includeDestroyed: false,
                progressNoun: 'pre-deployment',
            });
        },
        onStartLogPolling(options) {
            return setupLogPolling({
                auth,
                fetchFn,
                operationId: stack.operationId,
                stackId,
                onActivity: options.onActivity,
                onLogEntry: options.onLogEntry,
            });
        },
    });
    if (outcome.type === 'completed') {
        options.onPreDeployOperationDone?.();
    }
    else if (outcome.type === 'unconfirmed') {
        return {
            success: false,
            error: `Stack pre-deployment was accepted but completion could not be confirmed${outcome.error ? ` (${outcome.error})` : ''}.`,
            requestId,
            code: CODE_OPERATION_UNCONFIRMED,
            exitCode: EXIT_OPERATION_UNCONFIRMED,
            suggestions: [
                'The pre-deployment may or may not have finished on Sanity servers.',
                `Run \`${runCommand(bin)} blueprints info\` to check status.`,
                `Run \`${runCommand(bin)} blueprints logs --watch\` to keep streaming logs.`,
            ],
        };
    }
    else {
        return {
            success: false,
            error: 'Stack pre-deployment failed',
            requestId,
            suggestions: [
                ...outcome.logHints,
                'Review the pre-deployment output above for error details.',
                `Run \`${runCommand(bin)} blueprints logs --verbose\` for more context.`,
                `Run \`${runCommand(bin)} blueprints plan\` to identify issues with your Blueprint.`,
            ],
        };
    }
    return { success: true };
}
